"use client";

import { useState, useEffect } from "react";
import { X } from "lucide-react";
import { scheduledJobsApi, type ScheduledJob } from "@/lib/api";
import { useRouter } from "next/navigation";
import { CronPresetSelector, CRON_PRESETS } from "./CronPresetSelector";
import { NextRunsPreview } from "./NextRunsPreview";

interface EditScheduledJobModalProps {
  open: boolean;
  onClose: () => void;
  onSuccess: () => void;
  job: ScheduledJob;
}

export function EditScheduledJobModal({
  open,
  onClose,
  onSuccess,
  job,
}: EditScheduledJobModalProps) {
  const router = useRouter();
  const [cronSchedule, setCronSchedule] = useState(job.cron_schedule);
  const [isActive, setIsActive] = useState(job.is_active);
  const [showCustomCron, setShowCustomCron] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    if (open) {
      setCronSchedule(job.cron_schedule);
      setIsActive(job.is_active);
      const matchesPreset = CRON_PRESETS.some(
        (preset) => preset.value === job.cron_schedule
      );
      setShowCustomCron(!matchesPreset);
    }
  }, [open, job]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    try {
      await scheduledJobsApi.update(job.id, {
        cronSchedule,
        isActive,
      });

      onSuccess();
      onClose();
      router.refresh();
    } catch (err) {
      setError(
        err instanceof Error ? err.message : "Failed to update scheduled job"
      );
    } finally {
      setLoading(false);
    }
  };

  if (!open) return null;

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
      <div className="bg-white rounded-lg w-full max-w-md p-6 max-h-[90vh] overflow-y-auto">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-xl font-semibold">Edit Scheduled Job</h2>
          <button
            onClick={onClose}
            className="text-gray-500 hover:text-gray-700"
            aria-label="Close modal"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {error && (
          <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-md text-sm text-red-700">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          <CronPresetSelector
            value={cronSchedule}
            onChange={setCronSchedule}
            onCustom={() => setShowCustomCron(true)}
            showCustom={showCustomCron}
          />

          <NextRunsPreview cronSchedule={cronSchedule} />

          <div className="flex items-center gap-2">
            <input
              type="checkbox"
              id="isActive"
              checked={isActive}
              onChange={(e) => setIsActive(e.target.checked)}
              className="w-4 h-4"
            />
            <label htmlFor="isActive" className="text-sm">
              Active
            </label>
